import {Chess} from './chess.js';
import {guides,sources} from './guides.js';
import {arcaNotes} from './arca.js';
import {extraRatings} from './extra-ratings.js';
import {moveReason} from './lessons.js';
import {mountLearning,strategyCompare,appendTheorySources} from './learning-ui.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let database=[],active=null,step=0,mode='line',game=new Chess(),selected=null,flipped=false,timer=null,line=[],last=null,shown=45,filterCategory='',filterQuery='',filterLevel='',compareDisagree=false,freeStartFen=null;
const readStore=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let saved=readStore('atlas-saved',[]),done=readStore('atlas-completed',[]);
function persist(){try{localStorage.setItem('atlas-saved',JSON.stringify(saved));localStorage.setItem('atlas-completed',JSON.stringify(done))}catch{toast('이 브라우저에서는 학습 기록을 저장할 수 없습니다.')}}
if(readStore('atlas-dark',false))document.body.classList.add('dark');
$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('atlas-dark',JSON.stringify(document.body.classList.contains('dark')))}catch{}};
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function matches(g,q){return [g.name,g.en,g.eco,g.line,g.category].join(' ').toLowerCase().includes(q.toLowerCase())}
function sidebar(){const q=$('#search').value;let gs=guides.filter(g=>matches(g,q));$('#guide-count').textContent=guides.length;$('#side-list').innerHTML=['백 · e4','흑 · e4','백 · d4','흑 · d4','측면·시스템','백 · 안티 시실리안','백 · 프렌치 대응','백 · 카로칸 대응','흑 · 시실리안'].filter(c=>gs.some(g=>g.category===c)).map(cat=>`<div class="group-title">${esc(cat)}</div>${gs.filter(g=>g.category===cat).map(g=>`<a class="side-link ${active?.id===g.id?'selected':''}" href="#opening/${g.id}" ${active?.id===g.id?'aria-current="page"':''}><span>${esc(g.name)}</span><small>${done.includes(g.id)?'✓':''}</small></a>`).join('')}`).join('')||'<p class="small muted">일치하는 한국어 가이드가 없습니다. 전체 도감에서 영어 이름과 ECO도 검색하세요.</p>';}
$('#search').addEventListener('input',sidebar);$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){filterQuery=e.target.value;location.hash='library';library()}});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='/'){e.preventDefault();if(innerWidth<700)$('#sidebar').classList.add('open');$('#search').focus()}if(active&&mode==='line'){if(e.key==='ArrowRight')go(step+1);if(e.key==='ArrowLeft')go(step-1)}});
const tokens=pgn=>pgn.replace(/\d+\.(\.\.)?/g,'').trim().split(/\s+/).filter(Boolean);
const heading=(title,en,sub)=>`<div class="crumb"><a href="#library">체스</a><span>/</span><a href="#library">오프닝</a><span>/</span><span>${esc(title)}</span></div><div class="eyebrow">${esc(en)}</div><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p>`;
const cats=['백 · e4','흑 · e4','백 · d4','흑 · d4','측면·시스템','백 · 안티 시실리안','백 · 프렌치 대응','백 · 카로칸 대응','흑 · 시실리안'];
function filters(extra=''){return `<div class="filter-row"><input id="filter-query" placeholder="오프닝 이름, ECO 또는 수순" aria-label="도감 검색" value="${esc(filterQuery)}"><select id="filter-category" aria-label="상황 선택"><option value="">모든 상황</option>${cats.map(c=>`<option ${c===filterCategory?'selected':''}>${esc(c)}</option>`).join('')}</select>${extra}</div>`}
function bindFilters(fn){$('#filter-query').oninput=e=>{filterQuery=e.target.value;shown=45;fn()};$('#filter-category').onchange=e=>{filterCategory=e.target.value;shown=45;fn()}}
function related(g){let same=guides.filter(x=>x.id!==g.id&&x.category===g.category);return `<div class="related">${same.slice(0,5).map(x=>`<a href="#opening/${x.id}">${esc(x.name)}</a>`).join('')}</div>`}
function getCore(g){const seq=tokens(g.line);let found=null,length=0;for(const d of database){const ds=tokens(d.pgn);if(ds.length>length&&ds.length<=seq.length&&ds.every((m,i)=>m===seq[i])){found=d;length=ds.length}}return found?.eco??'—'}
function opening(g){freeStartFen=null;active=g;clearInterval(timer);timer=null;mode='line';step=0;selected=null;flipped=false;line=tokens(g.line);game.reset();last=null;sidebar();document.title=`${g.name} · 오프닝 아틀라스`;const isGuide=!!g.intro;
$('#main').innerHTML=`<div class="crumb"><a href="#library">오프닝 도감</a><span>/</span><span>${esc(g.category||'전체 수순 데이터')}</span><span>/</span><span>${esc(g.name)}</span></div><div class="title-row"><div><div class="eyebrow">${esc(g.en||g.eco+' · OPENING EXPLORER')}</div><h1>${esc(g.name)}</h1></div><button class="save" id="save">${saved.includes(g.id)?'★ 저장됨':'☆ 저장하기'}</button></div><p class="subtitle">${esc(g.intro||'Lichess 공개 데이터의 세부 수순입니다. 실제 폰 구조를 확인하고 가까운 한국어 전략 가이드와 연결해 연구하세요.')}</p><span class="badge">${esc(g.category||g.eco)}</span><span class="badge neutral">${esc(g.level||'수순 데이터')}</span>${done.includes(g.id)?'<span class="badge">연습 완료</span>':''}<div class="overview"><div><small>첫 수순</small><strong>${esc(line.slice(0,5).join(' '))}</strong></div><div><small>ECO 분류</small><strong>${esc(g.eco||getCore(g))}</strong></div><div><small>플레이 스타일</small><strong>${esc(g.style||'변형별로 다름')}</strong></div><div><small>이론 학습량</small><strong>${esc(g.theory||'별도 해설 없음')}</strong></div></div><section id="learn"><div class="workspace"><div class="board-card"><div class="board-head"><span>수순 따라가기</span><small id="turn-label">백 차례</small></div><div class="board-frame"><div class="board" id="board" aria-label="인터랙티브 체스판"></div></div><div class="board-controls"><div class="steps"><button id="start" aria-label="처음으로">⏮</button><button id="prev" aria-label="이전 수">‹</button><button id="play" aria-label="자동 재생">▶</button><button id="next" aria-label="다음 수">›</button><button id="end" aria-label="마지막으로">⏭</button></div><button id="flip" aria-label="체스판 뒤집기">↻</button></div><div class="mode-label" id="board-caption"></div></div><div class="panel"><div class="panel-top"><span>오프닝 연구실</span><small>${line.length}개 반수</small></div><div class="tabs"><button data-mode="line" class="active">수순 보기</button><button data-mode="train">직접 두기</button><button data-mode="free">자유 탐색</button></div><div class="panel-body" id="panel-body"></div></div></div></section>${isGuide?`<div class="article-grid"><article class="article"><section id="plans"><h2>양쪽의 계획</h2><div class="plans"><div class="plan"><h3>♔ 백의 계획</h3><p>${esc(g.white)}</p></div><div class="plan"><h3>♚ 흑의 계획</h3><p>${esc(g.black)}</p></div></div></section><section id="mistakes"><h2>실전에서 주의할 점</h2><div class="callout"><strong>수순을 외우기 전에</strong>${esc(g.caution)}</div>${g.id==='vienna'||g.id==='vienna-gambit'?`<h3>흑의 선택에 따라 계획이 달라집니다</h3><p class="small">2...Nf6 3.f4 뒤에는 흑의 3...d5 중앙 반격이 중요합니다. 3...exf4를 선택하면 4.e5로 나이트를 공격할 수 있습니다. 2...Nc6 뒤의 f4는 별도의 변형이므로 같은 수순을 기계적으로 적용하지 마세요.</p><p class="small muted">Nc3를 뒀다고 퀸의 h4 체크가 모든 상황에서 사라지는 것은 아닙니다. 또한 프랑켄슈타인–드라큘라 변형의 Qh5는 복잡한 전술의 시작이며, 강제로 기물을 얻는 간단한 함정으로 단정할 수 없습니다.</p>`:''}</section><section id="ratings"><h2>두 출처는 어떻게 평가했을까요?</h2><div class="tier-pair"><div class="tier-box"><small>체스프릭 · 초중급자</small><b>${esc(g.cf)}</b><a href="${sources[2].url}" target="_blank" rel="noopener">평가 원문 보기</a></div><div class="tier-box"><small>히카루·고담체스 · 게시글 요약</small><b>${esc(g.hk)}</b><a href="${sources[3].url}" target="_blank" rel="noopener">평가 원문 보기</a></div></div><p class="small muted" style="margin-top:14px">서로 다른 척도와 학습 기준의 주관적 평가입니다. —는 해당 항목의 평가가 없다는 뜻입니다. 세부 변형의 평가를 상위 오프닝 전체에 적용하지 않습니다.</p><a class="small" href="#compare">상황별 전체 비교 보기</a></section><section id="variations"><h2>관련 변형과 수순</h2><p class="small muted">아래 항목은 이름·ECO·수순 데이터입니다. 한국어 전략 가이드와 구분해 탐색하세요.</p><div id="variations-list"></div></section><section id="faq"><h2>자주 묻는 질문</h2><details><summary>이 수순을 상대가 그대로 두지 않으면 어떻게 하나요?</summary><p>외운 순서를 억지로 이어 가지 마세요. 체크와 기물 위협을 먼저 확인한 뒤 중앙, 전개, 킹의 안전을 기준으로 선택합니다. 자유 탐색에서 가능한 수를 직접 확인할 수 있습니다.</p></details><details><summary>티어가 낮으면 나쁜 오프닝인가요?</summary><p>아닙니다. 여기의 티어는 초보자의 학습과 실전 활용을 기준으로 한 출처별 의견입니다. 객관적인 엔진 평가나 모든 레이팅에 공통으로 적용되는 순위가 아닙니다.</p></details><details><summary>직접 두기는 어떤 방식인가요?</summary><p>선택한 대표 수순을 재현하는 연습입니다. 기물을 클릭하고 목적지 칸을 클릭하세요. 상대 수는 자동으로 진행됩니다. 다른 합법적인 수도 가능하지만 이 연습은 지정된 수순만 정답으로 처리합니다.</p></details></section><section><h2>이어서 살펴보기</h2>${related(g)}</section><div class="source-inline"><a href="#sources">자료 출처와 반영 상태</a><a href="https://github.com/lichess-org/chess-openings" target="_blank" rel="noopener">ECO·수순 데이터</a><a href="./chess-LICENSE.txt" target="_blank">체스 라이브러리 라이선스</a><a href="./pieces/NOTICE.txt" target="_blank">Cburnett 기물 이미지 출처</a></div></article><nav class="toc" aria-label="페이지 목차"><strong>이 페이지에서</strong><a href="#learn" data-scroll="learn">수순 따라가기</a><a href="#plans" data-scroll="plans">양쪽의 계획</a><a href="#mistakes" data-scroll="mistakes">주의할 점</a><a href="#ratings" data-scroll="ratings">출처별 평가</a><a href="#variations" data-scroll="variations">세부 변형</a><a href="#faq" data-scroll="faq">자주 묻는 질문</a></nav></div>`:`<div class="callout"><strong>공개 수순 데이터</strong>이 항목의 이름·ECO·수순은 Lichess 데이터에서 가져왔습니다. 이론상의 최선 수나 엔진 추천을 뜻하지 않습니다. <a href="#sources">출처 확인</a></div>`}`;
if(isGuide&&arcaNotes[g.id])$('#ratings').insertAdjacentHTML('beforeend',`<div class="callout"><strong>아카라이브 · 글쓴이의 입문 추천 관점</strong>${esc(arcaNotes[g.id])}<br><a class="small" href="${sources[4].url}" target="_blank" rel="noopener">원문 링크 · 사용자 제공 본문으로 반영</a></div>`);
$('#save').onclick=()=>{saved=saved.includes(g.id)?saved.filter(x=>x!==g.id):[...saved,g.id];persist();$('#save').textContent=saved.includes(g.id)?'★ 저장됨':'☆ 저장하기';toast(saved.includes(g.id)?'이 브라우저에 저장했습니다.':'저장을 해제했습니다.')};
$('#start').onclick=()=>go(0);$('#prev').onclick=()=>go(step-1);$('#next').onclick=()=>go(step+1);$('#end').onclick=()=>go(line.length);$('#flip').onclick=()=>{flipped=!flipped;renderBoard()};$('#play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('#play').textContent='▶'}else{if(step===line.length)go(0);timer=setInterval(()=>{if(step>=line.length){clearInterval(timer);timer=null;$('#play').textContent='▶'}else go(step+1)},950);$('#play').textContent='Ⅱ'}};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})});
if(isGuide){const family=g.id.startsWith('sicilian')?'Sicilian Defense':g.en.replace('Réti','Reti').replace('Queen’s',"Queen's").replace('King’s',"King's");const ds=database.filter(d=>d.name.toLowerCase().startsWith(family.toLowerCase())).slice(0,8);$('#variations-list').innerHTML=ds.length?`<div class="table-wrap"><table>${ds.map(d=>`<tr><td><a href="#data/${database.indexOf(d)}">${esc(d.name)}</a><div class="line-text">${esc(d.pgn)}</div></td><td>${d.eco}</td></tr>`).join('')}</table></div>`:'<p class="small muted">전체 도감에서 영어 이름이나 ECO 코드로 다른 변형을 검색할 수 있습니다.</p>';}
mountLearning(g,(pgn,label)=>{clearInterval(timer);timer=null;$('#play').textContent='▶';line=tokens(pgn);mode='line';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='line'));go(line.length);$('#board-caption').textContent=label+' · 대표 국면';$('#learn').scrollIntoView({behavior:'smooth'});toast('대표 국면을 보냈습니다. 자유 탐색으로 다음 수를 연구해 보세요.');});renderPanel();renderBoard();}
const pieceNames={p:'폰',n:'나이트',b:'비숍',r:'룩',q:'퀸',k:'킹'},symbols={p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚'};
function renderBoard(){const board=$('#board');if(!board)return;const ranks=flipped?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1],files=flipped?'hgfedcba':'abcdefgh';let legal=selected?game.moves({square:selected,verbose:true}).map(m=>m.to):[];board.innerHTML=ranks.flatMap((r,ri)=>[...files].map((f,fi)=>{let sq=f+r,p=game.get(sq);return `<button class="sq ${(f.charCodeAt(0)-97+r)%2===1?'dark-square':''} ${last&&(last.from===sq||last.to===sq)?'last':''} ${selected===sq?'chosen':''} ${legal.includes(sq)?'legal':''}" data-square="${sq}" aria-label="${p?(p.color==='w'?'백':'흑')+' '+pieceNames[p.type]+', ':''}${sq}">${p?`<img class="piece-img" src="./pieces/${p.color}${p.type.toUpperCase()}.svg" alt="" draggable="false">`:''}${fi===0?`<span class="coordinate">${r}</span>`:''}${ri===7?`<span class="coordinate file">${f}</span>`:''}</button>`})).join('');board.querySelectorAll('[data-square]').forEach(b=>b.onclick=()=>squareClick(b.dataset.square));$('#turn-label').textContent=(game.turn()==='w'?'백':'흑')+' 차례'+(game.isCheck()?' · 체크':'');$('#board-caption').textContent=mode==='line'?`대표 수순 · ${step} / ${line.length} 반수 · ← → 키로 이동`:mode==='train'?'기물을 선택한 뒤 목적지 칸을 선택하세요.':'합법적인 수를 자유롭게 두어 보세요.';['start','prev','next','end','play'].forEach(id=>$('#'+id).disabled=mode!=='line'||(['start','prev'].includes(id)?step===0:['next','end'].includes(id)?step===line.length:false));}
function go(n){if(mode!=='line')return;step=Math.max(0,Math.min(line.length,n));game.reset();last=null;for(let i=0;i<step;i++)last=game.move(line[i]);selected=null;renderBoard();renderPanel()}
const playerColor=()=>active?.category?.startsWith('흑')?'b':'w';
function setMode(m){clearInterval(timer);timer=null;$('#play').textContent='▶';if(m==='free'){if(mode!=='free')freeStartFen=game.fen();game=new Chess(freeStartFen||new Chess().fen())}else{game.reset();step=0}mode=m;selected=null;last=null;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='train')autoOpponent();renderBoard();renderPanel()}
function autoOpponent(){while(step<line.length&&game.turn()!==playerColor()){last=game.move(line[step]);step++}if(step===line.length&&!done.includes(active.id)){done.push(active.id);persist();sidebar()}}
function renderPanel(){const p=$('#panel-body');if(!p)return;$('.panel-top small').textContent=line.length+'개 반수';if(mode==='line'){p.innerHTML=`${active.id==='vienna'?`<select class="line-select" id="branch" aria-label="비엔나 변형 선택"><option value="main" ${line.includes('d5')?'selected':''}>대표 라인 · 중앙 반격 3...d5</option><option value="accept" ${line.includes('exf4')?'selected':''}>갬빗 수락 · 3...exf4</option><option value="quiet" ${!line.includes('f4')?'selected':''}>차분한 전개 · 3.Bc4</option></select>`:''}<div class="move-list">${line.map((m,i)=>`${i%2===0?`<small>${i/2+1}.</small>`:''}<button data-step="${i+1}" class="${step===i+1?'current':''}" aria-label="${Math.floor(i/2)+1}수 ${i%2?'흑':'백'} ${esc(m)}">${esc(m)}</button>`).join('')}</div><div class="callout"><strong>${step===0?'시작 국면':`${Math.ceil(step/2)}수 ${step%2?'백':'흑'} · ${esc(line[step-1])}`}</strong>${step===0?'다음 수로 이동하며 목적·위협·상대 대응을 함께 살펴보세요.':moveNote()}</div><button class="primary wide" id="begin-training">이 수순 직접 두기</button><p class="small muted" style="margin:10px 0 0">대표 예시 수순입니다. 모든 수가 강제되지는 않습니다.</p>`;p.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('#begin-training').onclick=()=>setMode('train');if($('#branch'))$('#branch').onchange=e=>{line=tokens(e.target.value==='accept'?'e4 e5 Nc3 Nf6 f4 exf4 e5 Ng8 Nf3 d6 d4':e.target.value==='quiet'?'e4 e5 Nc3 Nf6 Bc4 Nc6 d3 Bc5 Nf3 d6 O-O':'e4 e5 Nc3 Nf6 f4 d5 fxe5 Nxe4 Nf3 Be7 d3 Nxc3 bxc3 O-O');go(0)}}else if(mode==='train'){p.innerHTML=`<span class="badge">${playerColor()==='w'?'백':'흑'}으로 연습</span><h3 style="margin-top:16px">${step===line.length?'수순을 모두 완성했습니다.':'다음 수를 직접 두세요.'}</h3><p class="small muted">${step===line.length?'한 번 더 두며 기물의 목적을 기억해 보세요. 기록은 이 브라우저에 저장됩니다.':'대표 수순의 기물을 선택하고 목적지 칸을 클릭하세요. 상대 수는 자동으로 진행됩니다.'}</p><div class="callout" id="feedback" aria-live="polite"><strong>${step===line.length?'연습 완료':'진행 '+step+' / '+line.length+' 반수'}</strong>${step===line.length?'✓ 이 브라우저에 완료 기록을 남겼습니다.':'외운 수보다 중앙과 기물의 역할을 함께 떠올려 보세요.'}</div><button id="hint" ${step===line.length?'disabled':''}>힌트 보기</button> <button id="reset-training">다시 연습</button><div id="hint-text" class="small muted" style="margin-top:13px"></div>`;$('#hint').onclick=()=>{let c=new Chess(game.fen());let m=c.move(line[step]);$('#hint-text').textContent=`${pieceNames[m.piece]}: ${m.from} → ${m.to} (${m.san}) · ${moveReason(line.join(' '),step+1).why}`};$('#reset-training').onclick=()=>setMode('train')}else{p.innerHTML=`<h3>다른 수를 탐색해 보세요</h3><p class="small muted">선택한 기물의 합법적인 목적지가 표시됩니다. 엔진 평가와 상대 자동 응수는 제공하지 않습니다.</p><div class="callout"><strong>현재 기보</strong><span id="free-pgn">${esc(game.pgn().replace(/\[[^\]]*\]\s*/g,'').replace(/\s\*$/,'').trim()||'아직 수를 두지 않았습니다.')}</span></div><button id="free-undo">한 수 되돌리기</button> <button id="free-reset">연구 시작 국면으로</button><p class="small muted" style="margin-top:15px">폰 승진은 퀸으로 자동 처리합니다.</p><a id="lichess-link" class="small" href="https://lichess.org/analysis/standard/${game.fen().replace(/ /g,'_')}" target="_blank" rel="noopener">Lichess 분석판에서 열기</a>`;$('#free-undo').onclick=()=>{game.undo();last=game.history({verbose:true}).at(-1);selected=null;renderBoard();renderPanel()};$('#free-reset').onclick=()=>setMode('free')}}
function moveNote(){const n=moveReason(line.join(' '),step);return ['왜 두나요?','어떤 위협이 있나요?','상대가 무시한다면?'].map((t,i)=>`<div class="move-reason"><b>${t}</b><p>${esc([n.why,n.threat,n.ignore][i])}</p></div>`).join('')}
function squareClick(sq){if(mode==='line'){toast('직접 두기 또는 자유 탐색을 선택해 주세요.');return}if(mode==='train'&&step===line.length)return;let piece=game.get(sq);if(!selected||piece?.color===game.turn()){selected=piece?.color===game.turn()?sq:null;renderBoard();return}let from=selected;selected=null;let probe=new Chess(game.fen()),move;try{move=probe.move({from,to:sq,promotion:'q'})}catch{toast('그 칸으로 이동할 수 없습니다.');renderBoard();return}if(mode==='train'){let expected=new Chess(game.fen()).move(line[step]);if(move.from!==expected.from||move.to!==expected.to){$('#feedback').innerHTML='<strong>합법적인 수이지만 다른 수순입니다.</strong>이 연습에서는 선택한 대표 수순을 재현합니다. 힌트를 확인하거나 다시 선택하세요.';renderBoard();return}last=game.move({from,to:sq,promotion:'q'});step++;autoOpponent()}else last=game.move({from,to:sq,promotion:'q'});renderBoard();renderPanel()}
let libraryTab='guides';
function library(){active=null;clearInterval(timer);sidebar();document.title='오프닝 도감 · 오프닝 아틀라스';$('#main').innerHTML=heading('오프닝 도감','OPENING EXPLORER','상대의 첫 수부터 골라 보세요. 한국어 핵심 가이드에서 시작해 세부 변형까지 탐색할 수 있습니다.')+`<div class="compare-mode"><button id="guide-tab" class="${libraryTab==='guides'?'active':''}">한국어 가이드 ${guides.length}</button><button id="data-tab" class="${libraryTab==='data'?'active':''}">전체 수순 ${database.length.toLocaleString()}</button></div>`+filters(`<select id="filter-level" aria-label="학습 난이도"><option value="">모든 난이도</option>${['입문','중급','심화'].map(l=>`<option ${filterLevel===l?'selected':''}>${l}</option>`).join('')}</select>`)+`<div id="library-results"></div>`;$('#guide-tab').onclick=()=>{libraryTab='guides';shown=45;library()};$('#data-tab').onclick=()=>{libraryTab='data';shown=45;library()};bindFilters(renderLibrary);$('#filter-level').onchange=e=>{filterLevel=e.target.value;renderLibrary()};$('#filter-level').disabled=libraryTab==='data';renderLibrary()}
function renderLibrary(){if(libraryTab==='guides'){let gs=guides.filter(g=>matches(g,filterQuery)&&(!filterCategory||g.category===filterCategory)&&(!filterLevel||g.level===filterLevel));$('#library-results').innerHTML=`<div class="results-bar"><span>${gs.length}개 한국어 가이드</span><span>수순 · 폰 구조 · 미들게임 계획</span></div><div class="cards">${gs.map(g=>`<a class="card" href="#opening/${g.id}"><span class="badge neutral">${g.category}</span><h3 style="margin-top:15px">${g.name}</h3><div class="en">${esc(g.en)}</div><p>${esc(g.intro)}</p><footer>${g.level} · ${g.style} · 이론량 ${g.theory}${done.includes(g.id)?' · ✓ 연습 완료':''}</footer></a>`).join('')}</div>${!gs.length?'<div class="empty">검색 결과가 없습니다. 조건을 줄이거나 전체 수순에서 검색해 보세요.</div>':''}`}else{let searchQuery=filterQuery.toLowerCase();const translated=guides.find(g=>g.name===filterQuery)?.en.toLowerCase();let prefix=filterCategory.includes('d4')?'1. d4':filterCategory.includes('시실리안')?'1. e4 c5':filterCategory.includes('프렌치')?'1. e4 e6':filterCategory.includes('카로칸')?'1. e4 c6':filterCategory.includes('e4')?'1. e4':'';const alias=filterQuery.includes('시실리안')?'sicilian':filterQuery.includes('비엔나')?'vienna':filterQuery.includes('카로칸')?'caro-kann':filterQuery.includes('프렌치')?'french':translated;let ds=database.filter(d=>([d.name,d.eco,d.pgn,tokens(d.pgn).join(' ')].join(' ').toLowerCase().includes(searchQuery)||(alias&&d.name.toLowerCase().includes(alias)))&&(!prefix||d.pgn.startsWith(prefix)));$('#library-results').innerHTML=`<div class="results-bar"><span>${ds.length.toLocaleString()}개 수순 · ${Math.min(shown,ds.length)}개 표시</span><span>영어 원문 · ECO A–E</span></div><p class="small muted">전체 데이터는 진영별 추천이 아닌 수순 분류입니다. 상황 필터는 첫 수순으로 범위를 좁힙니다.</p><div class="table-wrap"><table><thead><tr><th>ECO</th><th>오프닝 / 수순</th></tr></thead><tbody>${ds.slice(0,shown).map(d=>`<tr><td>${d.eco}</td><td><a href="#data/${database.indexOf(d)}">${esc(d.name)}</a><div class="line-text">${esc(d.pgn)}</div></td></tr>`).join('')}</tbody></table></div>${ds.length>shown?'<button class="load-more" id="load-more">45개 더 보기</button>':''}${!ds.length?'<div class="empty">검색 결과가 없습니다.</div>':''}`;if($('#load-more'))$('#load-more').onclick=()=>{shown+=45;renderLibrary()}}}
function compare(){active=null;clearInterval(timer);sidebar();$('#main').innerHTML=heading('상황별 티어 비교','TWO PERSPECTIVES','같은 오프닝, 다른 학습 관점. 출처별 척도를 유지해 각 평가를 나란히 읽습니다.')+`<div class="callout"><strong>순위보다 맥락을 먼저 보세요</strong>체스프릭은 초중급자 학습·실전 활용 관점의 S–D 평가입니다. 히카루·고담체스는 별도의 주관적 척도입니다. 이 사이트는 둘을 합산해 새로운 티어를 만들지 않습니다.</div>`+filters()+`<label class="small"><input type="checkbox" id="disagree" ${compareDisagree?'checked':''}> 양쪽 평가가 모두 있는 항목만 보기</label><div id="compare-results"></div><p class="small muted" style="margin-top:20px">자료가 평가한 범위가 서로 다릅니다. —는 누락이며 낮은 티어가 아닙니다. 변형을 상위 오프닝과 동일시하지 않습니다.</p><div class="source-inline"><a href="${sources[2].url}" target="_blank" rel="noopener">체스프릭 정리 원문</a><a href="${sources[3].url}" target="_blank" rel="noopener">히카루·고담 정리 원문</a></div>`;bindFilters(renderComparison);$('#disagree').onchange=e=>{compareDisagree=e.target.checked;renderComparison()};renderComparison()}
function renderComparison(){let gs=[...guides,...extraRatings].filter(g=>matches(g,filterQuery)&&(!filterCategory||g.category===filterCategory)&&(!compareDisagree||g.cf!=='—'&&g.hk!=='—'));$('#compare-results').innerHTML=`<div class="results-bar"><span>${gs.length}개 항목</span><span>티어: 2023년 게시글 · 입문 의견: 제공 본문</span></div><div class="table-wrap"><table><thead><tr><th>오프닝</th><th>체스프릭</th><th>히카루·고담</th><th>아카라이브 입문 관점</th></tr></thead><tbody>${gs.map(g=>`<tr><td>${g.id?`<a href="#opening/${g.id}">${g.name}</a>`:esc(g.name)}<div class="small muted">${g.category}${g.id?'':' · 평가 자료만'}</div></td><td><span class="badge ${g.cf==='—'?'neutral':''}">${esc(g.cf)}</span></td><td>${esc(g.hk)}</td><td class="small muted">${esc(arcaNotes[g.id]||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function principles(){active=null;clearInterval(timer);sidebar();$('#main').innerHTML=heading('오프닝 학습 가이드','UNDERSTAND BEFORE YOU MEMORIZE','처음 열 수의 목적은 좋은 중반전을 준비하는 것입니다. 이름보다 기물의 역할과 폰 구조를 먼저 익혀 보세요.')+[['중앙을 다투세요','e4·d4·e5·d5를 폰과 기물로 통제하면 기물의 이동 공간을 얻습니다. 상대가 측면에서 공격하면 중앙을 열 수 있는지 확인하세요.'],['나이트와 비숍을 전개하세요','전술적인 이유가 없다면 같은 기물만 반복해 움직이기보다 아직 움직이지 않은 기물을 활용합니다. 모든 나이트를 비숍보다 먼저 둬야 하는 것은 아닙니다.'],['퀸의 이른 출격은 목적이 필요합니다','퀸을 공격하는 상대의 전개 수가 템포를 얻을 수 있습니다. 구체적인 전술이 성립할 때와 단순한 조기 출격을 구분하세요.'],['킹을 안전하게 두세요','캐슬링은 킹을 옮기고 룩을 연결할 준비를 합니다. 캐슬링할 날개의 폰 구조와 상대의 공격을 먼저 점검합니다.'],['룩을 연결하고 열린 열을 찾으세요','중앙에서 퀸과 비숍을 전개하면 룩 사이가 연결됩니다. 열린 열과 반쯤 열린 열에 룩을 배치하는 계획을 세웁니다.'],['작은 레퍼토리부터 시작하세요','백의 첫 수에 대한 한 가지 계획, 흑으로 e4·d4에 대한 한 가지 대응을 고릅니다. 대표 라인과 상대의 주요 다른 수를 함께 익히세요.'],['실전에서 벗어난 국면을 복습하세요','정석을 벗어났다고 나쁜 수는 아닙니다. 놓친 체크·잡기·위협, 전개 지연, 킹의 약화를 먼저 살펴보고 새 수순을 덧붙이세요.']].map(([t,p],i)=>`<div class="principle"><div class="num">0${i+1}</div><div><h2>${t}</h2><p>${p}</p></div></div>`).join('')+`<div class="callout"><strong>처음 시작할 때</strong>이탈리안과 비엔나에서 전개와 중앙 공격을 비교하고, 흑으로는 오픈 게임·카로칸의 구조를 비교해 보세요. 취향과 이해하기 쉬운 계획을 기준으로 선택합니다.</div><div class="related">${['italian','vienna','open-game','caro','london'].map(id=>`<a href="#opening/${id}">${guides.find(g=>g.id===id).name}</a>`).join('')}</div><p class="small muted" style="margin-top:20px">Royal Chess Mall의 전개 원칙과 오프닝 소개 주제를 바탕으로 새로 정리한 학습 안내입니다.</p>`}
function sourcePage(){active=null;clearInterval(timer);sidebar();$('#main').innerHTML=heading('자료 출처와 반영 상태','SOURCE NOTES','확인한 자료와 미확인 자료를 구분합니다. 설명은 새로 작성하고, 평가와 공개 수순에는 원문 출처를 연결했습니다.')+sources.map(s=>`<div class="source-card"><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><span class="badge neutral">${esc(s.status)}</span><p>${esc(s.note)}</p></div>`).join('')+`<div class="callout"><strong>자료를 통합할 때 바로잡은 부분</strong>스카치 게임은 기본 라인에서 폰을 되잡는 중앙 교환이며, 스카치 갬빗과 구분했습니다. 로솔리모는 ...Nc6, 모스크바는 ...d6에 대한 Bb5 대응입니다. 비엔나의 Nc3가 퀸 체크를 항상 없앤다는 표현과 복잡한 변형을 강제 기물 획득으로 설명하는 표현은 적용하지 않았습니다.</div><div class="source-card"><h3>아카라이브 본문 정리와 정정</h3><p>글쓴이의 최우선 추천은 이탈리안, 프렌치, 런던, 인디언 계열입니다. e4에 대한 8개 대응과 d4에 대한 d5·Nf6·f5·c5·Nc6·e5·e6·d6·g6 대응을 가이드와 수순 데이터로 연결했습니다.</p><p>프렌치 어드밴스의 3...c4는 해당 국면에서 불가능한 표기이므로 3...c5로 정정했습니다. 6.Bd3로 들어가는 밀너 베리 갬빗은 전체 수순 데이터에서 Milner-Barry로 검색할 수 있습니다.</p><p>포나이트의 4.Bc4 뒤 ...Nxe4와 ...d5는 포크를 활용하는 전술 주제입니다. 루이 로페즈는 이탈리안의 파생형이 아니라 별도 갈래입니다. 페트로프는 무승부를 강제하지 않으며, 1...d6와 1...Nf6 뒤에도 다양한 합법적 선택이 있습니다.</p><p>퀸즈 갬빗의 폰 회복은 무조건 확정되는 것이 아닙니다. d4가 항상 캐슬링을 늦추거나 닫힌 게임을 강제하는 것도 아닙니다. 원문의 승률·인기도와 유명 선수 인용은 검증된 통계나 직접 인용으로 재사용하지 않았습니다.</p></div><p class="small muted">수순은 chess.js로 합법성을 검증합니다. 엔진 평가, 최신 실전 통계, 승률을 제공하지 않습니다. 저장과 완료 기록은 현재 브라우저에만 보관됩니다.</p>`}
function savedPage(){active=null;clearInterval(timer);sidebar();const gs=saved.map(id=>guides.find(g=>g.id===id)??(id.startsWith('data-')?dataGuide(+id.slice(5)):null)).filter(Boolean);$('#main').innerHTML=heading('저장한 오프닝','YOUR LOCAL LIBRARY','이 브라우저에 저장한 오프닝을 이어서 살펴보세요.')+`<div class="cards">${gs.map(g=>`<a class="card" href="#${g.id.startsWith('data-')?'data/'+g.id.slice(5):'opening/'+g.id}"><h3>${esc(g.name)}</h3><p>${esc(g.category||g.eco)}</p><footer>${done.includes(g.id)?'✓ 연습 완료':'수순 학습 이어가기'}</footer></a>`).join('')}</div>${!gs.length?'<div class="empty">아직 저장한 오프닝이 없습니다.<br>오프닝 페이지에서 ☆ 저장하기를 눌러 보세요.<br><a href="#library">오프닝 도감 열기</a></div>':''}`}
function dataGuide(i){let d=database[i];return d?{id:'data-'+i,name:d.name,eco:d.eco,line:tokens(d.pgn).join(' ')}:null}
function route(){const hash=decodeURIComponent(location.hash.slice(1)||'opening/vienna');$('#sidebar').classList.remove('open');if(hash.startsWith('opening/')){let g=guides.find(g=>g.id===hash.slice(8));g?opening(g):library()}else if(hash.startsWith('data/')){let g=dataGuide(+hash.slice(5));g?opening(g):library()}else if(hash==='compare')compare();else if(hash==='strategy-compare'){active=null;clearInterval(timer);sidebar();strategyCompare();document.title='오프닝 전략 비교 · 오프닝 아틀라스'}else if(hash==='principles')principles();else if(hash==='sources'){sourcePage();appendTheorySources()}else if(hash==='saved')savedPage();else library();document.querySelectorAll('header nav a').forEach(a=>a.classList.toggle('active',a.hash===location.hash||(a.hash==='#library'&&active)));window.scrollTo(0,0)}
try{const r=await fetch('./database.json');if(!r.ok)throw Error('data');database=await r.json()}catch{$('#main').innerHTML='<div class="callout"><strong>세부 수순 데이터를 불러오지 못했습니다.</strong>핵심 한국어 가이드는 사용할 수 있습니다. 새로고침하면 다시 불러옵니다.</div>';toast('전체 수순 데이터가 아직 로드되지 않았습니다.')}
window.addEventListener('hashchange',route);sidebar();route();
